    "f4.desc": "Esami di prova a tempo di Hören e Lesen nel formato Goethe/ÖSD da A1 a B2, serie di esercizi, compiti di scrittura e serie di produzione orale, più un feedback facoltativo dell'IA (richiesto il consenso esplicito di persone adulte, dai 18 anni).",
    "f4.b1": "<strong>Esami di prova di Hören e Lesen:</strong> prove a tempo di Hören e Lesen da A1 a B2, con navigazione per passaggi e salti al punto dell'audio che contiene la risposta",
    "f4.b2": "<strong>Compiti di Schreiben e Sprechen:</strong> compiti di scrittura di Schreiben e serie di produzione orale di Sprechen con testi modello e valutazione facoltativa con IA dai 18 anni (con consenso esplicito, nei limiti del piano)",
