    "compare.c2Desc": "Âm thanh từng từ, giọng đọc truyện và các bài nghe, có thể chỉnh tốc độ phát và chế độ «Nghe trước».",
    "compare.c3Title": "Từ điển ngữ cảnh & SRS",
    "compare.c3Desc": "Chạm vào bất kỳ từ nào trong truyện hoặc phụ đề video để xem mạo từ (der/die/das), số nhiều và ghi chú ngữ pháp, rồi ôn lại các từ đã lưu bằng phương pháp lặp lại ngắt quãng.",
    "compare.c4Title": "Video tương tác & bài học theo lộ trình",
    "compare.c4Desc": "Các bài học có cấu trúc từ A1 đến B2, video tương tác có điểm kiểm tra theo từng cảnh, bài học Shorts, cùng công cụ về mạo từ, số đếm và lỗi sai.",
    "compare.c5Title": "Luyện tập theo định dạng Goethe & ÖSD",
    "compare.c5Desc": "Bài thi thử Hören và Lesen có tính giờ, bộ bài tập, bài Schreiben và bộ Sprechen. Định dạng luyện tập độc lập; không phải tài liệu chính thức của Goethe-Institut hay ÖSD.",
    "compare.c6Title": "Bắt đầu miễn phí · Gói trả phí qua cửa hàng ứng dụng",
    "compare.c6Desc": "Bắt đầu miễn phí với truyện A1 và các chương mẫu A2–B2; gói miễn phí có giới hạn sử dụng hằng ngày và sẽ được gỡ bỏ khi đăng ký gói trả phí.",
    "hero.badge": "SẮP RA MẮT · iOS & Android (bản web sắp có)",
    "hero.title": "Một chút <span class=\"highlight-gold\">tiếng Đức</span> trên mỗi trang cùng Fino. Bước nhỏ, câu chuyện lớn.",
    "hero.subtitle": "Học tiếng Đức với truyện âm thanh theo cấp độ (A1–B2), một tập video tương tác, từ điển ngữ cảnh chạm là học và các bài thi thử, bộ bài tập độc lập theo định dạng Goethe/ÖSD. Bắt đầu miễn phí; gói miễn phí có giới hạn sử dụng hằng ngày và sẽ được gỡ bỏ khi đăng ký gói trả phí.",
