const ASSET_BASE = (document.documentElement.getAttribute("data-base") || ".").replace(/\/+$/, "");
const PAGE_LANG = (document.documentElement.getAttribute("data-page-lang") || "").toLowerCase();

let currentLang = PAGE_LANG && I18N[PAGE_LANG] ? PAGE_LANG : "en";
let currentLevel = "A1";
let currentWordKey = "hinter";
let savedWords = new Set();
let currentAudioPlayer = null;

function resolveAssetPath(srcPath) {
  if (!srcPath) return srcPath;
  if (srcPath.startsWith("./")) return ASSET_BASE + srcPath.slice(1);
  return srcPath;
}

function detectInitialLang() {
  try {
    const params = new URLSearchParams(window.location.search);
    const qLang = params.get("lang");
    if (qLang && I18N[qLang.toLowerCase()]) return qLang.toLowerCase();
  } catch {}
  if (PAGE_LANG && I18N[PAGE_LANG]) return PAGE_LANG;
  return "en";
}

function switchPageLanguage(lang) {
  if (!I18N[lang]) return;
  try {
    localStorage.setItem("lernfino_web_lang", lang);
  } catch {}
  if (PAGE_LANG && lang !== PAGE_LANG && window.location.protocol !== "file:") {
    const hash = window.location.hash || "";
    const target = lang === "en" ? `${ASSET_BASE}/${hash}` : `${ASSET_BASE}/${lang}/${hash}`;
    window.location.href = target;
    return;
  }
  setLanguage(lang);
}

function interpretWaitlistResponse(ok, status, rawText) {
  let data = null;
  try {
    data = rawText ? JSON.parse(rawText) : null;
  } catch {
    data = null;
  }
  const statusVal = String((data && (data.status || data.result || data.state)) || "").toLowerCase();
  if (
    data &&
    (data.duplicate === true ||
      statusVal === "duplicate" ||
      statusVal === "already_registered" ||
      statusVal === "exists")
  ) {
    return { kind: "duplicate" };
  }
  if (
    ok &&
    data &&
    data.ok !== false &&
    data.success !== false &&
    (data.ok === true ||
      data.success === true ||
      statusVal === "ok" ||
      statusVal === "success" ||
      statusVal === "created" ||
      statusVal === "subscribed" ||
      statusVal === "added")
  ) {
    return { kind: "success" };
  }
  const reason = (data && (data.error || data.message)) || (status ? `HTTP ${status}` : "network");
  return { kind: "error", reason: String(reason) };
}

function stopAudio() {
  if (currentAudioPlayer) {
    currentAudioPlayer.pause();
    currentAudioPlayer.currentTime = 0;
    currentAudioPlayer = null;
  }
}

function playAudioFile(srcPath, fallbackWord) {
  stopAudio();
  if (srcPath) {
    const resolved = resolveAssetPath(srcPath.split("?")[0]);
    const cleanPath = resolved + "?v=qwen3";
    const audio = new Audio(cleanPath);
    currentAudioPlayer = audio;
    audio.play().catch(() => {
      if (fallbackWord) speakGermanSynthesis(fallbackWord);
    });
  } else if (fallbackWord) {
    speakGermanSynthesis(fallbackWord);
  }
}

function speakGermanSynthesis(text) {
  if (!("speechSynthesis" in window)) return;
  try {
    window.speechSynthesis.cancel();
    const utter = new SpeechSynthesisUtterance(text);
    utter.lang = "de-DE";
    utter.rate = 0.94;
    window.speechSynthesis.speak(utter);
  } catch {
    // Ignore speech synthesis errors
  }
}

function setLanguage(lang) {
  if (!I18N[lang]) return;
  currentLang = lang;
  localStorage.setItem("lernfino_web_lang", lang);
  document.documentElement.lang = lang;
  document.title = I18N[lang].pageTitle;

  // Update all [data-i18n] text
  const privacyUrl = resolveAssetPath("./privacy/#waitlist-privacy");
  document.querySelectorAll("[data-i18n]").forEach((el) => {
    const key = el.getAttribute("data-i18n");
    const val = I18N[lang][key];
    if (val !== undefined) {
      el.innerHTML = val.replace("{privacyUrl}", privacyUrl);
    }
  });

  // Update input placeholder
  const emailInput = document.getElementById("emailInput");
  if (emailInput) {
    emailInput.placeholder = I18N[lang]["launch.emailPlaceholder"];
  }

  // Update select options (Fix for dropdown options not translating)
  const levelSelect = document.getElementById("levelSelect");
  if (levelSelect) {
    const optMap = {
      A1: I18N[lang]["launch.optA1"],
      A2: I18N[lang]["launch.optA2"],
      B1: I18N[lang]["launch.optB1"],
      B2: I18N[lang]["launch.optB2"]
    };
    Array.from(levelSelect.options).forEach((opt) => {
      if (optMap[opt.value]) {
        opt.textContent = optMap[opt.value];
      }
    });
  }

  // Update language button active states
  document.querySelectorAll(".lang-btn").forEach((btn) => {
    const active = btn.getAttribute("data-lang") === lang;
    btn.classList.toggle("active", active);
    btn.setAttribute("aria-pressed", String(active));
  });

  const langSelectEl = document.getElementById("langSelect");
  if (langSelectEl) langSelectEl.value = lang;

  renderDemoStage();
  renderDictionaryCard();
}

function renderDemoStage() {
  const levelData = DEMO_LEVELS[currentLevel];
  const storyTitleEl = document.getElementById("demoStoryTitle");
  const badgeEl = document.getElementById("demoLevelBadge");
  const sentenceEl = document.getElementById("demoGermanSentence");
  const transEl = document.getElementById("demoSentenceTranslation");

  if (storyTitleEl) storyTitleEl.textContent = levelData.storyTitle;
  if (badgeEl) badgeEl.textContent = (levelData.badge[currentLang] || levelData.badge.en);
  if (transEl) transEl.textContent = (levelData.translation[currentLang] || levelData.translation.en);

  if (sentenceEl) {
    sentenceEl.innerHTML = "";
    levelData.words.forEach((tok) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "interactive-word" + (tok.key === currentWordKey ? " selected" : "");
      btn.textContent = tok.label;
      btn.addEventListener("click", () => {
        currentWordKey = tok.key;
        renderDemoStage();
        renderDictionaryCard();

        const entry = WORD_DICTIONARY[currentWordKey];
        if (entry) {
          playAudioFile(entry.audioFile, entry.headword);
        }
      });
      sentenceEl.appendChild(btn);
      sentenceEl.appendChild(document.createTextNode(" "));
    });
  }
}

function renderDictionaryCard() {
  const entry = WORD_DICTIONARY[currentWordKey] || WORD_DICTIONARY.hinter;
  document.getElementById("dictArticle").textContent = (entry.article[currentLang] || entry.article.en);
  document.getElementById("dictHeadword").textContent = entry.headword;
  document.getElementById("dictMeaning").textContent = (entry.meaning[currentLang] || entry.meaning.en);
  document.getElementById("dictGrammarNote").textContent = (entry.grammar[currentLang] || entry.grammar.en);
  document.getElementById("dictExampleDe").textContent = entry.exampleDe;
  document.getElementById("dictExampleTr").textContent = (entry.exampleTr[currentLang] || entry.exampleTr.en);
  document.getElementById("dictWordAudioLabel").textContent = I18N[currentLang]["demo.listenWord"];

  const saveBtn = document.getElementById("saveWordBtn");
  const saveIcon = document.getElementById("saveWordIcon");
  const saveText = document.getElementById("saveWordText");
  const isSaved = savedWords.has(currentWordKey);

  if (saveBtn && saveIcon && saveText) {
    saveIcon.textContent = isSaved ? "" : "＋";
    saveText.textContent = isSaved ? I18N[currentLang]["demo.savedBtn"] : I18N[currentLang]["demo.saveBtn"];
  }
}

document.addEventListener("DOMContentLoaded", () => {
  // Initialize Theme
  const savedTheme = localStorage.getItem("lernfino_web_theme");
  if (savedTheme === "dark" || savedTheme === "light") {
    document.documentElement.setAttribute("data-theme", savedTheme);
  }

  const themeToggle = document.getElementById("themeToggle");
  if (themeToggle) {
    themeToggle.addEventListener("click", () => {
      const current = document.documentElement.getAttribute("data-theme") || "light";
      const next = current === "light" ? "dark" : "light";
      document.documentElement.setAttribute("data-theme", next);
      localStorage.setItem("lernfino_web_theme", next);
    });
  }

  // Clear legacy localStorage waitlist email backup if present
  try {
    localStorage.removeItem("lernfino_waitlist");
  } catch {}

  // Preselect level from ?level= query parameter (e.g. from /level-test/)
  try {
    const qLevel = (new URLSearchParams(window.location.search).get("level") || "").toUpperCase();
    const levelSelectEl = document.getElementById("levelSelect");
    if (levelSelectEl && ["A1", "A2", "B1", "B2"].includes(qLevel)) {
      levelSelectEl.value = qLevel;
    }
  } catch {}

  // Language select (all 15 languages)
  const langSelect = document.getElementById("langSelect");
  if (langSelect) {
    langSelect.addEventListener("change", () => switchPageLanguage(langSelect.value));
  }

  // Language buttons
  document.querySelectorAll(".lang-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      const lang = btn.getAttribute("data-lang");
      if (lang) switchPageLanguage(lang);
    });
  });

  document.querySelectorAll("[data-lang-switch]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const lang = btn.getAttribute("data-lang-switch");
      if (lang) {
        switchPageLanguage(lang);
        if (!PAGE_LANG || window.location.protocol === "file:") {
          window.scrollTo({ top: 0, behavior: "smooth" });
        }
      }
    });
  });

  // CEFR Level Switcher
  document.querySelectorAll(".cefr-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      const lvl = btn.getAttribute("data-level");
      if (!lvl || !DEMO_LEVELS[lvl]) return;
      currentLevel = lvl;
      currentWordKey = DEMO_LEVELS[lvl].words[0].key;

      document.querySelectorAll(".cefr-btn").forEach((b) => {
        b.classList.toggle("active", b.getAttribute("data-level") === lvl);
      });

      renderDemoStage();
      renderDictionaryCard();
    });
  });

  // Speak Sentence (Plays real studio book audio!)
  const speakSentenceBtn = document.getElementById("speakSentenceBtn");
  if (speakSentenceBtn) {
    speakSentenceBtn.addEventListener("click", () => {
      const audioPath = DEMO_LEVELS[currentLevel].audioFile;
      playAudioFile(audioPath, null);
    });
  }

  // Speak Word (Plays real studio dictionary audio!)
  const speakWordBtn = document.getElementById("speakWordBtn");
  if (speakWordBtn) {
    speakWordBtn.addEventListener("click", () => {
      const entry = WORD_DICTIONARY[currentWordKey];
      if (entry) {
        playAudioFile(entry.audioFile, entry.headword);
      }
    });
  }

  // Save Word (SRS Simulation)
  const saveWordBtn = document.getElementById("saveWordBtn");
  if (saveWordBtn) {
    saveWordBtn.addEventListener("click", () => {
      if (savedWords.has(currentWordKey)) {
        savedWords.delete(currentWordKey);
      } else {
        savedWords.add(currentWordKey);
      }
      renderDictionaryCard();
    });
  }

  // Launch Notification Form (Required unchecked consent, verified CORS response, neutral duplicate handling, retry support)
  const notifyForm = document.getElementById("notifyForm");
  const emailInput = document.getElementById("emailInput");
  const consentCheckbox = document.getElementById("consentCheckbox");
  const levelSelect = document.getElementById("levelSelect");
  const formFeedback = document.getElementById("formFeedback");
  const feedbackMessage = document.getElementById("feedbackMessage");
  const feedbackFinoImg = formFeedback ? formFeedback.querySelector(".feedback-fino-img") : null;
  const formRetryBtn = document.getElementById("formRetryBtn");
  const GOOGLE_SHEET_URL = "https://script.google.com/macros/s/AKfycbz0gSh1Sguut_86bbIYPC1Dtd4Y7MxpNpJceBm8p7lxmB6bhQwha20FN-L49fGmtGEk/exec";

  function showFormFeedback(state, text, showRetry) {
    if (!formFeedback) return;
    formFeedback.classList.remove("is-pending", "is-duplicate", "is-error", "is-visible");
    if (state) formFeedback.classList.add(state);
    formFeedback.classList.add("is-visible");
    formFeedback.style.display = "flex";
    formFeedback.removeAttribute("hidden");
    if (feedbackFinoImg) {
      feedbackFinoImg.style.display = state === "is-error" ? "none" : "block";
    }
    if (feedbackMessage) {
      feedbackMessage.textContent = text;
    } else {
      formFeedback.textContent = text;
    }
    if (formRetryBtn) {
      formRetryBtn.hidden = !showRetry;
      formRetryBtn.textContent = I18N[currentLang]["launch.retryBtn"] || "Try Again";
    }
  }

  let isSubmittingWaitlist = false;

  async function submitWaitlist() {
    if (!notifyForm || !emailInput || !formFeedback || isSubmittingWaitlist) return;
    const email = emailInput.value.trim();
    const level = levelSelect ? levelSelect.value : "B1";
    if (!email) return;
    if (consentCheckbox && !consentCheckbox.checked) {
      showFormFeedback("is-error", I18N[currentLang]["launch.consentError"], false);
      consentCheckbox.focus();
      return;
    }

    const submitBtn = notifyForm.querySelector("button[type='submit']");
    isSubmittingWaitlist = true;
    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.style.opacity = "0.7";
    }
    showFormFeedback("is-pending", I18N[currentLang]["launch.pendingMsg"], false);

    try {
      const res = await fetch(GOOGLE_SHEET_URL, {
        method: "POST",
        mode: "cors",
        credentials: "omit",
        headers: {
          "Content-Type": "text/plain;charset=utf-8"
        },
        body: JSON.stringify({
          email: email,
          level: level,
          lang: currentLang,
          consent: true,
          source: "lernfino.com",
          page: window.location.pathname
        })
      });
      const rawText = await res.text();
      const outcome = interpretWaitlistResponse(res.ok, res.status, rawText);

      if (outcome.kind === "success") {
        const msg = I18N[currentLang]["launch.successMsg"].replace("{email}", email);
        showFormFeedback("", msg, false);
        emailInput.value = "";
        if (consentCheckbox) consentCheckbox.checked = false;
      } else if (outcome.kind === "duplicate") {
        showFormFeedback("is-duplicate", I18N[currentLang]["launch.duplicateMsg"], false);
      } else {
        const errMsg = I18N[currentLang]["launch.errorMsg"].replace("{reason}", outcome.reason);
        showFormFeedback("is-error", errMsg, true);
      }
    } catch (err) {
      const reason = err && err.message ? err.message : "network";
      const errMsg = I18N[currentLang]["launch.errorMsg"].replace("{reason}", reason);
      showFormFeedback("is-error", errMsg, true);
    } finally {
      isSubmittingWaitlist = false;
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.style.opacity = "";
      }
    }
  }

  if (notifyForm && emailInput && formFeedback) {
    notifyForm.addEventListener("submit", (e) => {
      e.preventDefault();
      submitWaitlist();
    });
    if (formRetryBtn) {
      formRetryBtn.addEventListener("click", () => {
        submitWaitlist();
      });
    }
  }

  // Initial render
  setLanguage(detectInitialLang());
});
